function P({questions:W=[],level:g="intermediate",difficultyPref:a="mixed_easy_medium",dailyHours:m=2,targetDays:p=45,includeRevision:f=!0,startDate:y=new Date().toISOString().split("T")[0],existingCompletedIds:_=[]}){const x={beginner:{Easy:25,Medium:45,Hard:70},intermediate:{Easy:18,Medium:32,Hard:50},advanced:{Easy:12,Medium:22,Hard:35}}[g]||{Easy:18,Medium:32,Hard:50};let h=W.map(e=>{const t=_.includes(e.id)||e.completed;return{...e,completed:t,estimatedMinutes:x[e.difficulty]||30}});const N=h.reduce((e,t)=>e+t.estimatedMinutes,0);let n=[...h];if(a==="easy_first"){const e={Easy:1,Medium:2,Hard:3};n.sort((t,i)=>e[t.difficulty]!==e[i.difficulty]?e[t.difficulty]-e[i.difficulty]:t.week-i.week)}else if(a==="mostly_medium"){const e={Medium:1,Easy:2,Hard:3};n.sort((t,i)=>e[t.difficulty]!==e[i.difficulty]?e[t.difficulty]-e[i.difficulty]:t.week-i.week)}else if(a==="hard_focus"){const e={Hard:1,Medium:2,Easy:3};n.sort((t,i)=>e[t.difficulty]!==e[i.difficulty]?e[t.difficulty]-e[i.difficulty]:t.week-i.week)}else n.sort((e,t)=>e.week-t.week||e.number-t.number);const l=n.filter(e=>!e.completed),I=n.filter(e=>e.completed),M=l.reduce((e,t)=>e+t.estimatedMinutes,0),u=Math.max(1,Math.min(Math.round(p)||45,l.length||1)),w=e=>f&&e%5===0?.7:1,D=Array.from({length:u},(e,t)=>w(t+1)).reduce((e,t)=>e+t,0),k=M/D/60;let E=null;l.length>0&&k>m*1.15&&(E=`Finishing in ${u} days means about ${k.toFixed(1)} h a day, more than the ${m} h you set. Pick a later date or more hours if that is too much.`);const d=[],S=new Date(y);let r=0,C=0,F=0;for(let e=1;e<=u&&r<n.length;e++){const t=new Date(S);t.setDate(S.getDate()+(e-1));const i=t.toISOString().split("T")[0],T=f&&e%5===0;F+=w(e);const $=M*(F/D),A=e===u,o=[];let H=0;for(;r<n.length;){const s=n[r],c=s.completed?0:s.estimatedMinutes,O=o.some(v=>!v.completed);if(!A&&O&&c>0&&C+c/2>$)break;o.push(s),H+=c,C+=c,r++}d.push({dayNumber:e,date:i,topics:Array.from(new Set(o.map(s=>s.topic))),questions:o,totalEstimatedMinutes:H,isRevisionDay:T,completedCount:o.filter(s=>s.completed).length,isFullyCompleted:o.length>0&&o.every(s=>s.completed)})}const Q=d.length>0?d[d.length-1].date:y;return{config:{level:g,difficultyPref:a,dailyHours:m,targetDays:p,includeRevision:f,startDate:y},warning:E,totalQuestions:h.length,completedCount:I.length,remainingCount:l.length,totalEstimatedMinutes:N,estimatedDaysNeeded:d.length,estimatedCompletionDate:Q,revisionQueue:[],days:d}}export{P as generateScheduleClient};
